import pandas as pd

from rfm.scorer import WEIGHTS, add_scores, quintile_score


def test_quintile_scores_in_range_1_to_5():
    series = pd.Series(range(100), dtype=float)
    scores = quintile_score(series)
    assert set(scores.unique()) <= {1, 2, 3, 4, 5}
    assert scores.value_counts().eq(20).all()


def test_recency_is_inverted():
    # fewer recency days -> better score
    rfm = pd.DataFrame(
        {
            "recency_days": [10.0, 50.0],
            "frequency": [5.0, 1.0],
            "monetary": [500.0, 100.0],
        }
    )
    scored = add_scores(rfm)
    assert scored["r"].iloc[0] > scored["r"].iloc[1]


def test_composite_weights():
    assert WEIGHTS == {"r": 0.5, "f": 0.3, "m": 0.2}
    rfm = pd.DataFrame(
        {
            "recency_days": [5.0],
            "frequency": [9.0],
            "monetary": [900.0],
        }
    )
    scored = add_scores(rfm)
    expected = round(0.5 * scored["r"][0] + 0.3 * scored["f"][0] + 0.2 * scored["m"][0], 6)
    assert scored["composite"][0] == expected


def test_scoring_is_order_independent():
    a = pd.DataFrame(
        {
            "recency_days": [1.0, 20.0, 300.0],
            "frequency": [7.0, 3.0, 1.0],
            "monetary": [800.0, 200.0, 50.0],
        }
    )
    shuffled = a.sample(frac=1.0, random_state=0)
    scored_a = add_scores(a)
    scored_b = add_scores(shuffled).sort_index()
    pd.testing.assert_frame_equal(scored_a, scored_b)

