import pandas as pd

from rfm.loader import compute_rfm, load_transactions


def _make_df(rows):
    return pd.DataFrame(rows, columns=["customer_id", "date", "amount"]).assign(
        date=lambda d: pd.to_datetime(d["date"])
    )


def test_compute_rfm_metrics(tmp_path):
    df = _make_df(
        [
            (1, "2025-01-01", 10.0),
            (1, "2025-03-01", 25.0),
            (2, "2025-07-01", 100.0),
        ]
    )
    rfm = compute_rfm(df, pd.Timestamp("2025-08-15"))
    assert rfm.loc[1, "recency_days"] == 167
    assert rfm.loc[1, "frequency"] == 2
    assert rfm.loc[1, "monetary"] == 35.0
    assert rfm.loc[2, "recency_days"] == 45
    assert rfm.loc[2, "monetary"] == 100.0


def test_transactions_after_asof_are_ignored(tmp_path):
    df = _make_df([(1, "2025-09-01", 10.0)])
    try:
        compute_rfm(df, pd.Timestamp("2025-08-15"))
    except ValueError:
        pass
    else:
        raise AssertionError("expected ValueError when nothing is on/before asof")


def test_load_missing_column_raises(tmp_path):
    path = tmp_path / "bad.csv"
    path.write_text("customer_id,date\n1,2025-01-01\n")
    try:
        load_transactions(path)
    except ValueError:
        pass
    else:
        raise AssertionError("expected ValueError for missing columns")

